            try {
                this.value = Objects.requireNonNull(reducer.apply(v, value), "The reducer returned a null value");
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                upstream.dispose();
                onError(ex);
            }
        }
    }

