}

@Override
public final boolean isEmpty() {
    Iterator<? extends T> it = this.iterator;
    if (it != null) {
        if (!once || it.hasNext()) {
            return false;
        }
        clear();
    }
    return true;
}

@Override
public final void clear() {
    iterator = null;
}

